//! Trie nodes backing the persistent vector.
//!
//! The vector is a bitmapped radix-balanced trie: every interior node has up to
//! `BRANCHING` children and every leaf holds up to `BRANCHING` elements. Nodes
//! are shared between vector versions through `Rc`, so copying a vector never
//! copies elements and `push_back` only rebuilds the spine it touches.

use std::rc::Rc;

/// Number of index bits consumed per trie level.
pub const BITS: u32 = 5;

/// Maximum number of children (or elements) per node: 32.
pub const BRANCHING: usize = 1 << BITS;

/// Mask selecting the index bits of a single level.
pub const MASK: usize = BRANCHING - 1;

pub enum Node<T> {
    /// Interior node; children are stored densely, left to right.
    Branch(Vec<Rc<Node<T>>>),
    /// Bottom level node holding the elements themselves.
    Leaf(Vec<T>),
}

impl<T> Node<T> {
    pub fn empty_branch() -> Rc<Node<T>> {
        Rc::new(Node::Branch(Vec::new()))
    }

    pub fn leaf(elements: Vec<T>) -> Rc<Node<T>> {
        Rc::new(Node::Leaf(elements))
    }

    /// Children of an interior node.
    ///
    /// # Panics
    /// Panics when called on a leaf, which would mean the `shift` recorded by
    /// the vector disagrees with the tree's actual depth.
    pub fn children(&self) -> &[Rc<Node<T>>] {
        match self {
            Node::Branch(children) => children,
            Node::Leaf(_) => panic!("immer::vector: expected a branch node, found a leaf"),
        }
    }

    /// Elements of a leaf node.
    ///
    /// # Panics
    /// Panics when called on an interior node (see [`Node::children`]).
    pub fn elements(&self) -> &[T] {
        match self {
            Node::Leaf(elements) => elements,
            Node::Branch(_) => panic!("immer::vector: expected a leaf node, found a branch"),
        }
    }

    /// Copy of this branch with `child` stored at `index`.
    ///
    /// `index` either replaces an existing child or extends the node by one
    /// slot; the dense layout of children makes those the only valid cases.
    pub fn with_child(&self, index: usize, child: Rc<Node<T>>) -> Rc<Node<T>> {
        let mut children = self.children().to_vec();
        if index < children.len() {
            children[index] = child;
        } else {
            debug_assert_eq!(index, children.len(), "branch children must stay dense");
            children.push(child);
        }
        Rc::new(Node::Branch(children))
    }
}

/// Builds the chain of interior nodes needed to hang `leaf` at `level`.
///
/// `level` is the shift of the returned node, so `level == BITS` yields the
/// leaf itself and each extra level wraps it in a single-child branch.
pub fn new_path<T>(level: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    if level == BITS {
        leaf
    } else {
        Rc::new(Node::Branch(vec![new_path(level - BITS, leaf)]))
    }
}

