//! An immutable (persistent) vector, mirroring the API of `immer::vector<T>`.
//!
//! Every mutating-looking operation returns a *new* vector and leaves the
//! receiver untouched, which is what lets the C++ original write
//! `v = v.push_back(i)` in a loop. Versions share their unchanged subtrees, so
//! a push copies at most one leaf plus the interior nodes on the path to it
//! rather than the whole sequence.
//!
//! The representation is a bitmapped radix-balanced trie with a *tail*: the
//! last (up to 32) elements live in a flat buffer outside the trie, so the
//! common case of repeated appends only clones that small buffer. When the tail
//! fills up it is pushed into the trie as a leaf, growing the trie by one level
//! whenever the root runs out of capacity.

use std::fmt;
use std::iter::FromIterator;
use std::ops::Index;
use std::rc::Rc;

use super::node::{new_path, Node, BITS, BRANCHING, MASK};

pub struct Vector<T> {
    /// Total number of elements, trie plus tail.
    count: usize,
    /// Bits of index consumed by the root; the trie's depth in disguise.
    shift: u32,
    /// Trie holding the first `count - tail.len()` elements.
    root: Rc<Node<T>>,
    /// Flat buffer holding the trailing elements.
    tail: Rc<Vec<T>>,
}

impl<T> Vector<T> {
    /// An empty vector. Allocation-free apart from the shared empty root.
    pub fn new() -> Vector<T> {
        Vector {
            count: 0,
            shift: BITS,
            root: Node::empty_branch(),
            tail: Rc::new(Vec::new()),
        }
    }

    /// Number of elements, matching `immer::vector::size`.
    pub fn size(&self) -> usize {
        self.count
    }

    /// Idiomatic alias for [`Vector::size`].
    pub fn len(&self) -> usize {
        self.count
    }

    pub fn is_empty(&self) -> bool {
        self.count == 0
    }

    /// Index of the first element stored in the tail.
    ///
    /// Always a multiple of `BRANCHING`, since the tail is only flushed into
    /// the trie once it is completely full.
    fn tail_offset(&self) -> usize {
        self.count - self.tail.len()
    }

    /// The leaf buffer containing `index`, together with the index of its
    /// first element.
    fn leaf_for(&self, index: usize) -> &[T] {
        debug_assert!(index < self.count);
        let tail_offset = self.tail_offset();
        if index >= tail_offset {
            return &self.tail;
        }
        let mut node: &Node<T> = &self.root;
        let mut level = self.shift;
        while level > BITS {
            node = &node.children()[(index >> level) & MASK];
            level -= BITS;
        }
        node.children()[(index >> BITS) & MASK].elements()
    }

    pub fn get(&self, index: usize) -> Option<&T> {
        if index >= self.count {
            return None;
        }
        Some(&self.leaf_for(index)[index & MASK])
    }

    /// Last element, or `None` when empty.
    pub fn back(&self) -> Option<&T> {
        self.count.checked_sub(1).and_then(|last| self.get(last))
    }

    /// First element, or `None` when empty.
    pub fn front(&self) -> Option<&T> {
        self.get(0)
    }

    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            vector: self,
            index: 0,
            leaf: &[],
            leaf_base: usize::MAX,
        }
    }
}

impl<T: Clone> Vector<T> {
    /// Returns a new vector with `value` appended; `self` is unchanged.
    pub fn push_back(&self, value: T) -> Vector<T> {
        // Fast path: room left in the tail, so only the tail buffer is copied.
        if self.tail.len() < BRANCHING {
            let mut tail = (*self.tail).clone();
            tail.push(value);
            return Vector {
                count: self.count + 1,
                shift: self.shift,
                root: Rc::clone(&self.root),
                tail: Rc::new(tail),
            };
        }

        // The tail is full: it becomes a leaf of the trie.
        let tail_node = Node::leaf((*self.tail).clone());
        let (root, shift) = if (self.count >> BITS) > (1 << self.shift) {
            // The root is saturated; deepen the trie by one level, with the
            // old root and the new leaf's path as the two children.
            let root = Node::Branch(vec![
                Rc::clone(&self.root),
                new_path(self.shift, tail_node),
            ]);
            (Rc::new(root), self.shift + BITS)
        } else {
            (self.push_tail(self.shift, &self.root, tail_node), self.shift)
        };

        Vector {
            count: self.count + 1,
            shift,
            root,
            tail: Rc::new(vec![value]),
        }
    }

    /// Rebuilds the path from `parent` down to the slot the flushed tail
    /// belongs in, copying only the nodes along that path.
    fn push_tail(&self, level: u32, parent: &Rc<Node<T>>, tail_node: Rc<Node<T>>) -> Rc<Node<T>> {
        // `count - 1` is the last index of the tail being flushed, which maps
        // to exactly the slot the new leaf should occupy.
        let subidx = ((self.count - 1) >> level) & MASK;
        let to_insert = if level == BITS {
            tail_node
        } else {
            match parent.children().get(subidx) {
                Some(child) => self.push_tail(level - BITS, child, tail_node),
                None => new_path(level - BITS, tail_node),
            }
        };
        parent.with_child(subidx, to_insert)
    }

    /// Returns a new vector with `index` replaced by `value`.
    ///
    /// # Panics
    /// Panics if `index` is out of bounds.
    pub fn set(&self, index: usize, value: T) -> Vector<T> {
        assert!(
            index < self.count,
            "immer::vector: index {} out of range for size {}",
            index,
            self.count
        );

        if index >= self.tail_offset() {
            let mut tail = (*self.tail).clone();
            tail[index - self.tail_offset()] = value;
            Vector {
                count: self.count,
                shift: self.shift,
                root: Rc::clone(&self.root),
                tail: Rc::new(tail),
            }
        } else {
            Vector {
                count: self.count,
                shift: self.shift,
                root: assoc(self.shift, &self.root, index, value),
                tail: Rc::clone(&self.tail),
            }
        }
    }
}

/// Copy-on-write descent used by [`Vector::set`]; `level` is the shift of `node`.
fn assoc<T: Clone>(level: u32, node: &Rc<Node<T>>, index: usize, value: T) -> Rc<Node<T>> {
    if level == 0 {
        let mut elements = node.elements().to_vec();
        elements[index & MASK] = value;
        Node::leaf(elements)
    } else {
        let subidx = (index >> level) & MASK;
        let child = assoc(level - BITS, &node.children()[subidx], index, value);
        node.with_child(subidx, child)
    }
}

/// Cheap: shares the whole structure with the original.
impl<T> Clone for Vector<T> {
    fn clone(&self) -> Vector<T> {
        Vector {
            count: self.count,
            shift: self.shift,
            root: Rc::clone(&self.root),
            tail: Rc::clone(&self.tail),
        }
    }
}

impl<T> Default for Vector<T> {
    fn default() -> Vector<T> {
        Vector::new()
    }
}

impl<T> Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        match self.get(index) {
            Some(value) => value,
            None => panic!(
                "immer::vector: index {} out of range for size {}",
                index, self.count
            ),
        }
    }
}

pub struct Iter<'a, T> {
    vector: &'a Vector<T>,
    index: usize,
    leaf: &'a [T],
    /// Index of `leaf[0]` within the vector; `usize::MAX` until first refill.
    leaf_base: usize,
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.index >= self.vector.len() {
            return None;
        }
        // Leaves are aligned to multiples of `BRANCHING`, so the cached buffer
        // is refreshed once every 32 elements.
        let base = self.index & !MASK;
        if base != self.leaf_base {
            self.leaf = self.vector.leaf_for(self.index);
            self.leaf_base = base;
        }
        let item = &self.leaf[self.index - self.leaf_base];
        self.index += 1;
        Some(item)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.vector.len() - self.index;
        (remaining, Some(remaining))
    }
}

impl<'a, T> ExactSizeIterator for Iter<'a, T> {}

impl<'a, T> IntoIterator for &'a Vector<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Iter<'a, T> {
        self.iter()
    }
}

impl<T: Clone> FromIterator<T> for Vector<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Vector<T> {
        iter.into_iter()
            .fold(Vector::new(), |vector, value| vector.push_back(value))
    }
}

impl<T: PartialEq> PartialEq for Vector<T> {
    fn eq(&self, other: &Vector<T>) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a == b)
    }
}

impl<T: Eq> Eq for Vector<T> {}

impl<T: fmt::Debug> fmt::Debug for Vector<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_list().entries(self.iter()).finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_vector_has_no_elements() {
        let v: Vector<i32> = Vector::new();
        assert_eq!(v.size(), 0);
        assert!(v.is_empty());
        assert_eq!(v.get(0), None);
        assert_eq!(v.back(), None);
    }

    #[test]
    fn push_back_leaves_the_original_untouched() {
        let a = Vector::new().push_back(1);
        let b = a.push_back(2);
        assert_eq!(a.size(), 1);
        assert_eq!(b.size(), 2);
        assert_eq!(a.get(1), None);
        assert_eq!(b[1], 2);
    }

    /// Spans several trie levels: 32^2 elements forces two root overflows.
    #[test]
    fn indexing_matches_insertion_order_across_levels() {
        let n = 5000;
        let mut v = Vector::new();
        for i in 0..n {
            v = v.push_back(i);
        }
        assert_eq!(v.size(), n);
        for i in 0..n {
            assert_eq!(v[i], i, "wrong element at {}", i);
        }
        assert_eq!(v.front(), Some(&0));
        assert_eq!(v.back(), Some(&(n - 1)));
    }

    #[test]
    fn iteration_visits_every_element_in_order() {
        let v: Vector<usize> = (0..2000).collect();
        assert_eq!(v.iter().count(), 2000);
        assert!(v.iter().copied().eq(0..2000));
    }

    #[test]
    fn set_replaces_one_element_only() {
        let v: Vector<usize> = (0..1500).collect();
        let w = v.set(1234, 99);
        assert_eq!(v[1234], 1234);
        assert_eq!(w[1234], 99);
        assert_eq!(w.size(), v.size());
        assert!(w.iter().enumerate().all(|(i, &x)| x == if i == 1234 { 99 } else { i }));
    }

    #[test]
    fn equality_and_debug_follow_element_order() {
        let a: Vector<i32> = (0..40).collect();
        let b: Vector<i32> = (0..40).collect();
        assert_eq!(a, b);
        assert_ne!(a, b.push_back(40));
        assert_eq!(format!("{:?}", (0..3).collect::<Vector<i32>>()), "[0, 1, 2]");
    }
}

