//! `std::stoi` reimplemented on top of the standard library.
//!
//! Rust's `str::parse::<i32>()` is stricter than the C++ function: it rejects
//! surrounding whitespace and any trailing characters, whereas `std::stoi`
//! (which wraps `strtol`) skips leading whitespace, reads an optional sign and
//! as many decimal digits as it can, and simply ignores whatever follows. The
//! difference is observable — `stoi(" 42abc")` is `42` — so the C++ rules are
//! spelled out here rather than delegated to `parse`.

/// The two failures `std::stoi` reports, as C++ exception types.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    /// No digits could be read: `std::invalid_argument`.
    InvalidArgument,
    /// Digits were read but the value does not fit in `int`: `std::out_of_range`.
    OutOfRange,
}

impl StoiError {
    /// Name of the C++ exception class, as printed by a terminate handler.
    pub fn exception_name(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }
}

/// Characters `std::isspace` accepts in the C locale.
fn is_cpp_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r')
}

/// Converts the leading decimal integer in `text`, following `std::stoi(text)`.
pub fn stoi(text: &str) -> Result<i32, StoiError> {
    let bytes = text.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() && is_cpp_space(bytes[pos]) {
        pos += 1;
    }

    let negative = match bytes.get(pos) {
        Some(b'-') => {
            pos += 1;
            true
        }
        Some(b'+') => {
            pos += 1;
            false
        }
        _ => false,
    };

    // Magnitude is tracked separately from the sign so that the asymmetric
    // lower bound (`-2147483648` is valid, `2147483648` is not) falls out.
    const MAX_MAGNITUDE: i64 = i32::MAX as i64 + 1;
    let mut magnitude: i64 = 0;
    let mut digits = 0;
    let mut overflowed = false;

    while let Some(&byte) = bytes.get(pos) {
        if !byte.is_ascii_digit() {
            break;
        }
        digits += 1;
        pos += 1;
        if !overflowed {
            magnitude = magnitude * 10 + i64::from(byte - b'0');
            if magnitude > MAX_MAGNITUDE {
                // Keep consuming the remaining digits, but stop accumulating:
                // the result is already out of range either way.
                overflowed = true;
            }
        }
    }

    if digits == 0 {
        return Err(StoiError::InvalidArgument);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_plain_decimals() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("5"), Ok(5));
        assert_eq!(stoi("+7"), Ok(7));
        assert_eq!(stoi("-42"), Ok(-42));
    }

    #[test]
    fn skips_leading_space_and_ignores_trailing_junk() {
        assert_eq!(stoi(" \t\n42"), Ok(42));
        assert_eq!(stoi("3abc"), Ok(3));
        assert_eq!(stoi("12 34"), Ok(12));
        // Base 10 only: parsing stops at the 'x'.
        assert_eq!(stoi("0x10"), Ok(0));
    }

    #[test]
    fn rejects_input_without_digits() {
        assert_eq!(stoi(""), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("abc"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("   "), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("-"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("+x1"), Err(StoiError::InvalidArgument));
    }

    #[test]
    fn honours_the_int_range() {
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
        assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("99999999999999999999"), Err(StoiError::OutOfRange));
    }
}

