/// Ends the process the way an uncaught C++ exception does.
///
/// The original binary lets `std::stoi` throw out of `main`, so libstdc++'s
/// terminate handler prints the exception type and `what()` to stderr and
/// aborts. Reproducing both the message and the `SIGABRT` exit keeps failing
/// inputs observationally identical to the C++ program.
pub fn terminate_with_uncaught_exception(exception_name: &str, what: &str) -> ! {
    let _ = std::io::stdout().flush();
    let mut stderr = std::io::stderr();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of '{}'",
        exception_name
    );
    let _ = writeln!(stderr, "  what():  {}", what);
    let _ = stderr.flush();
    std::process::abort()
}

